style.css:
@-moz-document domain("google.com") {
/* Aplicar imagen de fondo al cuerpo de la página */
    body {
        background-image: url("https://wallpapercave.com/wp/wp13943912.jpg") !important;
        background-size: cover !important;
        background-position: center center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
    }

    /* Ajuste de transparencia en elementos principales para lucir el fondo */
    .L3eUfd, .sfbg, .gb_1d, .gb_Zd {
        background: transparent !important;
    }

    /* Estilo semi-transparente para la barra de búsqueda */
    .RNNXzb {
        background: rgba(255, 255, 255, 0.85) !important;
        backdrop-filter: blur(5px) !important;
        border-radius: 24px !important;
    }
}
